INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(32411, 'Matthew 9:15', 'Matthew', 9, 15, 'عیسی هغوی ته وویل: «ایا دا کېدای شي چې د زوم ملګري دې په داسې حال کې چې زوم ورسره وي خفه ناست وي؟ بې له شکه چې نه. خو داسې وخت به راشي چې زوم به د هغوی نه بوتلل شي، نو بیا به روژه نیسي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew9_verse_15.mp3', '', 1761754199, 1761754199),
(32412, 'Matthew 9:16', 'Matthew', 9, 16, 'هېڅوک په زړو کالیو باندې نوی پیوند نه لګوي. که داسې وکړي نو هغه پیوند به د زړو کالیو څخه راوشلیږي او د مخکې نه به هم یو لوی سوری په کې جوړ شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew9_verse_16.mp3', '', 1761754199, 1761754199),
(32413, 'Matthew 9:17', 'Matthew', 9, 17, 'او نه هم څوک تازه شراب په زړو مشکونو کې اچوي، ځکه که واچول شي، نو مشکونه شکیږي او شراب ترې توییږي او مشکونه به له منځه لاړ شي. خو تازه شراب په نویو مشکونو کې اچول کیږي او په دې ډول هم شراب او هم مشک دواړه روغ پاتې کیږي.» یوې ښځې ته شفا ورکول او د یوې مړې انجلۍ راژوندي کول (مرقوس ۵‏:‌۲۱‌‏-‌۴۳ او لوقا ۸‏:‌۴۰‌‏-‌۵۶)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew9_verse_17.mp3', '', 1761754199, 1761754199),
(32414, 'Matthew 9:18', 'Matthew', 9, 18, 'عیسی لا دا خبرې کولې چې په دې وخت کې د کنیسې یو مشر ورته راغی او د هغه په پښو کې پرېوت او ویې ویل: «همدا‌اوس زما لور مړه شوه، خو که چېرې ته راشې او خپل لاس ورباندې کېږدې، نو هغه به ژوندۍ شي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew9_verse_18.mp3', '', 1761754199, 1761754199),
(32415, 'Matthew 9:19', 'Matthew', 9, 19, 'عیسی پاڅېد او ورسره روان شو او شاګردان یې هم ورپسې روان شول.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew9_verse_19.mp3', '', 1761754199, 1761754199),
(32416, 'Matthew 9:20', 'Matthew', 9, 20, 'په دې وخت کې یوه ښځه چې د دولسو کالو راهیسې ورڅخه وینه بهېدله، د شا له خوا راغله او د عیسی لمنې ته یې لاس وروړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew9_verse_20.mp3', '', 1761754199, 1761754199),
(32417, 'Matthew 9:21', 'Matthew', 9, 21, 'ځکه چې هغې باور درلود چې که زه یوازې د هغه چپنې ته هم لاس وروړم نو روغه به شم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew9_verse_21.mp3', '', 1761754199, 1761754199),
(32418, 'Matthew 9:22', 'Matthew', 9, 22, 'عیسی مخ ورواړاوه او هغه یې ولیدله او ورته ویې ویل: «لورې! ډاډه اوسه، ته خپل ایمان روغه کړې.» او په هماغه ساعت ښځه روغه شوه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew9_verse_22.mp3', '', 1761754199, 1761754199),
(32419, 'Matthew 9:23', 'Matthew', 9, 23, 'کله چې عیسی د هغه مشر کور ته ورغی او د جنازې دپاره د غم ساز غږوونکي او د خلکو شور یې ولیده،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew9_verse_23.mp3', '', 1761754199, 1761754199),
(32420, 'Matthew 9:24', 'Matthew', 9, 24, 'نو هغه وویل: «ووځئ، ځکه چې انجلۍ مړه نه ده، بلکې ویده ده.» نو هغوی ورپورې وخندل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew9_verse_24.mp3', '', 1761754199, 1761754199),
(32421, 'Matthew 9:25', 'Matthew', 9, 25, 'خو کله چې ټول خلک دباندې وویستل شول، نو هغه د انجلۍ کوټې ته ورننوت، هغه یې له لاسه ونیوله او هغه راپاڅېدله.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew9_verse_25.mp3', '', 1761754199, 1761754199),
(32422, 'Matthew 9:26', 'Matthew', 9, 26, 'دا خبر په هغې ټولې سیمې کې خپور شو. عیسی دوو ړندو ته شفا ورکوي', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew9_verse_26.mp3', '', 1761754199, 1761754199),
(32423, 'Matthew 9:27', 'Matthew', 9, 27, 'کله چې عیسی د هغه ځای نه روان شو، نو دوه ړانده ورپسې روان شول او چیغې یې وهلې: «ای د داود زویه، په مونږ رحم وکړه.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew9_verse_27.mp3', '', 1761754199, 1761754199),
(32424, 'Matthew 9:28', 'Matthew', 9, 28, 'کله چې عیسی کور ته دننه شو، نو هغه ړانده ورته راغلل. عیسی د هغوی څخه پوښتنه وکړه: «ایا تاسو په دې ایمان لرئ چې زه کولای شم تاسو بینا کړم؟» هغوی وویل: «هو، ښاغلیه!»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew9_verse_28.mp3', '', 1761754199, 1761754199),
(32425, 'Matthew 9:29', 'Matthew', 9, 29, 'بیا عیسی د هغوی سترګو ته لاس وروړ او ویې ویل: «څنګه چې ستاسو ایمان دی، نو همداسې دې وشي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew9_verse_29.mp3', '', 1761754199, 1761754199),
(32426, 'Matthew 9:30', 'Matthew', 9, 30, 'او د هغوی سترګې بینا شوې. عیسی هغوی ته په کلکه خبرداری ورکړ چې په دې هکله هېچا ته څه ونه وایي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew9_verse_30.mp3', '', 1761754199, 1761754199),
(32427, 'Matthew 9:31', 'Matthew', 9, 31, 'خو کله چې هغوی لاړل، نو په هغه ټوله سیمه کې یې د هغه په هکله خبر خپور کړ. عیسی یو ګونګي ته شفا ورکوي', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew9_verse_31.mp3', '', 1761754199, 1761754199),
(32428, 'Matthew 9:32', 'Matthew', 9, 32, 'کله چې عیسی او شاګردان یې په وتلو کې وو چې یو سړی یې عیسی ته راوست چې خبرې یې نه شوې کولای ځکه چې پېریانو نیولی ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew9_verse_32.mp3', '', 1761754199, 1761754199),
(32429, 'Matthew 9:33', 'Matthew', 9, 33, 'کله چې عیسی د هغه څخه پېری وویست، نو هغه سړي په خبرو پیل وکړ. خلک ډېر حیران شول او ویې ویل: «په اسراییلو کې هېڅکله هم داسې کار نه دی لیدل شوی.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew9_verse_33.mp3', '', 1761754199, 1761754199),
(32430, 'Matthew 9:34', 'Matthew', 9, 34, 'خو فریسیانو وویل: «هغه د پېریانو د مشر یعنې شیطان په مرسته پېریان وباسي.» عیسی په خلکو باندې رحم کوي', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew9_verse_34.mp3', '', 1761754199, 1761754199),
(32431, 'Matthew 9:35', 'Matthew', 9, 35, 'عیسی ښار په ښار او کلي په کلي ګرځېده او د هغوی په کنیسو کې یې تعلیم ورکاوه او د اسماني پاچاهۍ زېری یې خپراوه او د خلکو هر ډول ناروغۍ او کمزورتیاوې یې روغولې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew9_verse_35.mp3', '', 1761754199, 1761754199),
(32432, 'Matthew 9:36', 'Matthew', 9, 36, 'کله چې هغه د خلکو ګڼه‌ګوڼه ولیدله، نو زړه یې ورباندې وسوځېد، ځکه چې هغوی د بې‌شپونه پسونو په شان پرېشانه او بې‌وسه وو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew9_verse_36.mp3', '', 1761754199, 1761754199),
(32433, 'Matthew 9:37', 'Matthew', 9, 37, 'بیا هغه خپلو شاګردانو ته وویل: «فصل ډېر دی، خو مزدوران لږ دي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew9_verse_37.mp3', '', 1761754199, 1761754199),
(32434, 'Matthew 9:38', 'Matthew', 9, 38, 'نو تاسو د فصل خاوند ته زاري وکړئ چې د خپلو حاصلاتو د راټولولو دپاره نور مزدوران راولېږي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew9_verse_38.mp3', '', 1761754199, 1761754199),
(32435, 'Matthew 21:1', 'Matthew', 21, 1, 'کله چې عیسی او شاګردان یې اورشلیم ته نژدې شول او بیت‌فاجي ته چې د زیتون په غره کې ؤ ورسېدل، نو عیسی خپل دوه شاګردان ولېږل', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew21_verse_1.mp3', '', 1761754199, 1761754199),
(32436, 'Matthew 21:2', 'Matthew', 21, 2, 'او هغوی ته یې وویل: «هغه مخامخ کلي ته ورشئ، نو هلته به یوه خره ووینئ چې د خپل کوټي سره به تړل شوې وي. هغه را‌ایله کړئ او ماته یې راولئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew21_verse_2.mp3', '', 1761754199, 1761754199),
(32437, 'Matthew 21:3', 'Matthew', 21, 3, 'که چا درته څه وویل نو ورته ووایئ: ‹دا زمونږ د استاذ په کار دي› نو هغه به سمدلاسه تاسو ته اجازه درکړي چې هغه بوځئ.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew21_verse_3.mp3', '', 1761754199, 1761754199),
(32438, 'Matthew 21:4', 'Matthew', 21, 4, 'په دې ډول به د پیغمبر هغه وینا رښتیا شي چې وایي:', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew21_verse_4.mp3', '', 1761754199, 1761754199),
(32439, 'Matthew 21:5', 'Matthew', 21, 5, 'د صهیون خلکو ته ووایئ چې ستاسو پاچا درروان دی چې عاجز دی او په خره باندې سپور دی، یعنې د خرې په کوټي باندې سپور دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew21_verse_5.mp3', '', 1761754199, 1761754199),
(32440, 'Matthew 21:6', 'Matthew', 21, 6, 'شاګردان لاړل او څنګه چې عیسی ورته ویلي وو هماغسې یې وکړل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew21_verse_6.mp3', '', 1761754199, 1761754199),
(32441, 'Matthew 21:7', 'Matthew', 21, 7, 'هغوی خره او کوټی راوستل او خپلې چپنې یې ورباندې واچولې او عیسی ورباندې سپور شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew21_verse_7.mp3', '', 1761754199, 1761754199),
(32442, 'Matthew 21:8', 'Matthew', 21, 8, 'ډېرو زیاتو خلکو ورته په لاره کې خپل کالي وغوړول او ځینو خلکو د ونو څانګې راپرې کړلې او په لاره کې یې ورته واچولې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew21_verse_8.mp3', '', 1761754199, 1761754199),
(32443, 'Matthew 21:9', 'Matthew', 21, 9, 'کوم خلک چې د هغه څخه مخکې او وروسته روان وو چیغې یې وهلې: «ژوندی دې وي د داود زوی، مبارک دی هغه څوک چې د څښتن په نوم راځي. ثنا دې وي څښتن تعالی ته.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew21_verse_9.mp3', '', 1761754199, 1761754199),
(32444, 'Matthew 21:10', 'Matthew', 21, 10, 'کله چې عیسی اورشلیم ته ورننوت، نو په ټول ښار کې شور او غوغا ګډه شوه، خلکو پوښتنه کوله: «دا څوک دی؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew21_verse_10.mp3', '', 1761754199, 1761754199),
(32445, 'Matthew 21:11', 'Matthew', 21, 11, 'نو کوم خلک چې د عیسی سره ملګري وو ځواب یې ورکړ: «دا عیسی پیغمبر دی چې د جلیل د ناصرې څخه راغلی دی.» عیسی د خدای د کور څخه سوداګران شړي (مرقوس ۱۱‏:‌۱۵‌‏-‌۱۹ او لوقا ۱۹‏:‌۴۵‌‏-‌۴۸ او یوحنا ۲‏:‌۱۳‌‏-‌۲۲)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew21_verse_11.mp3', '', 1761754199, 1761754199),
(32446, 'Matthew 21:12', 'Matthew', 21, 12, 'عیسی د خدای کور ته ننوت او له هغه ځای څخه یې د خرڅوونکو او اخیستونکو په شړلو پیل وکړ او د صرافانو مېزونه او د کوترو خرڅوونکو چوکۍ‌ګانې یې په بل مخ واړولې،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew21_verse_12.mp3', '', 1761754199, 1761754199),
(32447, 'Matthew 21:13', 'Matthew', 21, 13, 'او هغوی ته یې وویل: «د خدای په کلام کې لیکل شوي دي: زما کور به د دعا د کور په نوم یادیږي. خو تاسو ترې د غلو د پټېدلو ځای جوړ کړی دی.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew21_verse_13.mp3', '', 1761754199, 1761754199),
(32448, 'Matthew 21:14', 'Matthew', 21, 14, 'د خدای په کور کې ورته ړانده او ګوډان راغلل او هغوی ته یې شفا ورکړه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew21_verse_14.mp3', '', 1761754199, 1761754199),
(32449, 'Matthew 21:15', 'Matthew', 21, 15, 'خو کله چې مشرانو کاهنانو او د شریعت عالمانو د عیسی حیرانوونکې معجزې چې هغه ښودلې، ولیدلې او د خدای په کور کې یې د ماشومانو چیغې واورېدلې چې ویل یې: «د داود زوی ته دې ثنا وي.» نو هغوی خفه شول.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew21_verse_15.mp3', '', 1761754199, 1761754199),
(32450, 'Matthew 21:16', 'Matthew', 21, 16, 'نو د عیسی څخه یې پوښتنه وکړه: «دا ماشومان چې څه وایي ته یې اورې؟» عیسی ځواب ورکړ: «هو، زه یې اورم. ایا تاسو د خدای په کلام کې نه دي لوستلي: خدایه ته به ماشومانو او تي رودونکو ته دا ورزده کوې چې ستا ثنا ووایي؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew21_verse_16.mp3', '', 1761754199, 1761754199),
(32451, 'Matthew 21:17', 'Matthew', 21, 17, 'عیسی هغوی پرېښودل او د ښار څخه ووت. بیت‌عنیا ته لاړ او هلته یې شپه تېره کړه. عیسی د انځر په ونې لعنت وایي (مرقوس ۱۱‏:‌۱۲‌‏-‌۱۴، ۱۱‏:‌۲۰‌‏-‌۲۴)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew21_verse_17.mp3', '', 1761754199, 1761754199),
(32452, 'Matthew 21:18', 'Matthew', 21, 18, 'سبا سهار کله چې عیسی بېرته اورشلیم ته راتله، نو وږی شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew21_verse_18.mp3', '', 1761754199, 1761754199),
(32453, 'Matthew 21:19', 'Matthew', 21, 19, 'د سرک په غاړه یې د انځر ونه ولیدله نو هغه ورته ورغی، خو په هغې کې یې له پاڼو پرته بل هېڅ شی ونه لیده. نو هغې ونې ته یې وویل: «ته دې نور هېڅکله مېوه ونه نیسې.» او سمدلاسه هغه ونه وچه شوه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew21_verse_19.mp3', '', 1761754199, 1761754199),
(32454, 'Matthew 21:20', 'Matthew', 21, 20, 'کله چې شاګردانو دا ولیدل، نو حیران شول او پوښتنه یې وکړه: «دا د انځر ونه دومره زر څنګه وچه شوه؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew21_verse_20.mp3', '', 1761754199, 1761754199),
(32455, 'Matthew 21:21', 'Matthew', 21, 21, 'عیسی ورته ځواب ورکړ: «په یقین سره زه تاسو ته دا وایم چې که چېرې تاسو ایمان ولرئ او شک ونه کړئ، نو تاسو به هم وکولای شئ داسې کار وکړئ لکه څنګه چې ما د انځر د ونې سره وکړ. یوازې دا کار نه بلکې که تاسو دې غره ته هم ووایئ چې پورته شه او بحیرې ته وغورځېږه، نو همداسې به وشي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew21_verse_21.mp3', '', 1761754199, 1761754199),
(32456, 'Matthew 21:22', 'Matthew', 21, 22, 'که تاسو ایمان ولرئ، نو هرڅه چې په دعا کې وغواړئ هغه به لاسته راوړئ.» د عیسی د اختیار په هکله پوښتنه (مرقوس ۱۱‏:‌۲۷‌‏-‌۳۳ او لوقا ۲۰‏:‌۱‌‏-‌۸)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew21_verse_22.mp3', '', 1761754199, 1761754199),
(32457, 'Matthew 21:23', 'Matthew', 21, 23, 'عیسی بېرته د خدای کور ته راغی او تعلیم یې ورکاوه چې مشران کاهنان او د قوم مشران ورته راغلل او پوښتنه یې ترې وکړه: «چا تاته دا حق درکړی چې دا کارونه کوې؟ تاته چا دا واک او اختیار درکړی دی چې دا کارونه وکړې؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew21_verse_23.mp3', '', 1761754199, 1761754199),
(32458, 'Matthew 21:24', 'Matthew', 21, 24, 'عیسی ځواب ورکړ: «زه هم ستاسو څخه یوه پوښتنه کوم، که تاسو ځواب راکړ نو زه به هم درته ووایم چې زه په کوم اختیار سره دا کارونه کوم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew21_verse_24.mp3', '', 1761754199, 1761754199),
(32459, 'Matthew 21:25', 'Matthew', 21, 25, 'تعمید ورکوونکي یحیی ته دا اختیار چا ورکړی ؤ چې خلکو ته د تعمید غسل ورکړي؟ هغه د خدای له خوا ؤ یا د انسان له خوا؟» هغوی په خپل منځ کې سره بحث وکړ او ویل یې: «که چېرې ووایو د خدای له خوا ؤ، نو هغه به ووایي چې بیا تاسو ولې په هغه باندې ایمان رانه وړ؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew21_verse_25.mp3', '', 1761754199, 1761754199),
(32460, 'Matthew 21:26', 'Matthew', 21, 26, 'خو که چېرې ووایو چې د انسان له خوا ؤ، نو د خلکو څخه وېرېږو ځکه چې هغوی ټول یحیی پیغمبر ګڼي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew21_verse_26.mp3', '', 1761754199, 1761754199),
(32461, 'Matthew 21:27', 'Matthew', 21, 27, 'نو هغوی عیسی ته په ځواب کې وویل: «مونږ نه پوهېږو.» عیسی ورته وویل: «نو زه هم تاسو ته نه وایم چې په کوم اختیار دا کارونه کوم.» د دوو زامنو مثال', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew21_verse_27.mp3', '', 1761754199, 1761754199),
(32462, 'Matthew 21:28', 'Matthew', 21, 28, 'عیسی زیاته کړه: «تاسو په دې هکله څه فکر کوئ؟ یو سړی ؤ چې دوه زامن یې لرل. هغه خپل مشر زوی ته ورغی او ورته ویې ویل: ‹زویه! لاړ شه او نن د انګورو په باغ کې کار وکړه.›', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew21_verse_28.mp3', '', 1761754199, 1761754199),
